DATA_B64=""
import ast,base64,collections,copy,hashlib,json
d=json.loads(base64.b64decode(DATA_B64));old=ast.parse(d['before']);new=ast.parse(d['after']);checks=[]
def need(n,v):
    if not v:raise AssertionError(n)
    checks.append(n)
def dump(x):return ast.dump(x,include_attributes=False)
def src(text,n):return ast.get_source_segment(text,n)
defs=lambda tree:{n.name:n for n in tree.body if isinstance(n,(ast.FunctionDef,ast.ClassDef,ast.AsyncFunctionDef))}
before,after=defs(old),defs(new)
need('same11_top_definitions',set(before)==set(after) and len(before)==11)
unchanged=[]
for name in before:
    if name not in ('predicate_projection','main'):
        need(name+':byte_exact_definition',src(d['before'],before[name])==src(d['after'],after[name]));unchanged.append(name)
need('exact9_unchanged_definitions',len(unchanged)==9)
need('all_original_rejection_guards_AST_exact',[dump(n) for n in ast.walk(old) if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id=='need']==[dump(n) for n in ast.walk(new) if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id=='need'])
assigns={n.targets[0].id:n.value for n in new.body if isinstance(n,ast.Assign) and len(n.targets)==1 and isinstance(n.targets[0],ast.Name)}
prior=json.loads(d['prior'])['predicateProjection']['enabledHarnessOwners']
expected={str(x['registryOrdinal']):[x['identifierValueSha256'],x['rootValueSha256'],x['agentHarnessesMetadataSha256']] for x in prior}
need('exact_original_observed_two_hash_triples',ast.literal_eval(assigns['CATALOG_RECORD_PINS'])==expected and set(expected)=={'22','68'})
need('exact_public_SDK_root_literal',dump(assigns['PUBLIC_SDK_ROOT'])==dump(ast.parse("Path('/opt/homebrew/lib/node_modules/openclaw')",mode='eval').body))
caps={'NEW_SOFT_SECONDS':5.0,'MAX_METADATA_CALLS':80,'MAX_DESCRIPTORS':9,'MAX_READ_CALLS':4,'MAX_READ_BYTES':195156,'MAX_OUTPUT_BYTES':16384}
for key,value in caps.items():need(key+':unchanged',ast.literal_eval(assigns[key])==value)
oldcap=next(n.value for n in old.body if isinstance(n,ast.Assign) and isinstance(n.targets[0],ast.Name) and n.targets[0].id=='CAPSULE')
need('private_capsule_exact_input_unchanged',dump(oldcap)==dump(assigns['CAPSULE']))
root_gate=next(n.value for n in ast.walk(after['predicate_projection']) if isinstance(n,ast.Assign) and isinstance(n.targets[0],ast.Name) and n.targets[0].id=='catalog_public')
expected_gate=ast.parse('bool(id_matches and root_constructible and absolute and normalized and str(root) == raw_root and re.fullmatch(r"/[A-Za-z0-9_.@+~/-]{1,4095}", raw_root) and len(raw_root.encode("utf-8")) <= 4096 and (known_root or public_sdk_root) and catalog_values_match)',mode='eval').body
need('exact_conjunctive_public_disclosure_gate',dump(root_gate)==dump(expected_gate))
def callname(call):
    return ast.unparse(call.func)
oldcalls=collections.Counter(callname(n) for n in ast.walk(old) if isinstance(n,ast.Call));newcalls=collections.Counter(callname(n) for n in ast.walk(new) if isinstance(n,ast.Call));added=newcalls-oldcalls
allowed={'bool','root.is_relative_to','CATALOG_RECORD_PINS.get','str','sha','encoded','re.fullmatch','len','raw_root.encode','any'}
need('new_calls_lexical_or_memory_only',set(added)<=allowed)
rows={'publicCatalogPluginId':'identifier if catalog_public else None','publicCatalogCodeRoot':'str(root) if catalog_public else None','publicCatalogScope':'("already_pinned_codex" if known_root else "fixed_public_sdk_tree") if catalog_public else None','catalogMetadataOnlyNotCodeAdmission':'True'}
found={}
for node in ast.walk(after['predicate_projection']):
    if isinstance(node,ast.Dict):
        for key,value in zip(node.keys,node.values):
            if isinstance(key,ast.Constant) and key.value in rows:found[key.value]=value
for key,expression in rows.items():need(key+':exact_explicit_projection',dump(found[key])==dump(ast.parse(expression,mode='eval').body))
need('no_new_dict_unpack',sum(isinstance(n,ast.Dict) and any(k is None for k in n.keys) for n in ast.walk(old))==sum(isinstance(n,ast.Dict) and any(k is None for k in n.keys) for n in ast.walk(new)))
class Normalize(ast.NodeTransformer):
    def visit_Assign(self,node):
        if len(node.targets)==1 and isinstance(node.targets[0],ast.Name) and node.targets[0].id in {'PUBLIC_SDK_ROOT','CATALOG_RECORD_PINS','public_sdk_root','catalog_pin','catalog_values_match','catalog_public'}:return None
        return self.generic_visit(node)
    def visit_Dict(self,node):
        pairs=[]
        for key,value in zip(node.keys,node.values):
            k=key.value if isinstance(key,ast.Constant) else None
            if k in set(rows)|{'publicCatalogDisclosureScope','newFilesystemPathsRead','sdkOrLoaderExecuted'}:continue
            if k in {'pluginIdsPublished','unknownCodePathsPublished'}:value=ast.Constant(False)
            pairs.append((key,self.visit(value)))
        node.keys=[k for k,v in pairs];node.values=[v for k,v in pairs];return node
    def visit_Constant(self,node):
        if node.value=='heptabao.mac-captured-public-harness-catalog.r2':node.value='heptabao.mac-captured-harness-predicate-observation.r1'
        if isinstance(node.value,str) and node.value.startswith('After loader.t(onlyPluginIds), selector.o(provider/modelId)'):node.value=node.value.replace('After loader.t(', 'After loader.r(',1)
        return node
normalized=Normalize().visit(copy.deepcopy(new))
normalized.body[0]=copy.deepcopy(old.body[0])
need('entire_AST_only_declared_narrow_changes',dump(normalized)==dump(old))
need('main_only_schema_literal_change',dump(defs(normalized)['main'])==dump(before['main']))
result={'schema':'heptabao.root-auth-captured-catalog-source-AST-review.r29.v1','status':'PASS_NARROW_SOURCE_AND_DISCLOSURE_GATE_ONLY','checks_passed':len(checks),'checks':checks,'unchanged_definitions':unchanged,'added_memory_only_call_counts':dict(added),'old_source_sha256':hashlib.sha256(d['before'].encode()).hexdigest(),'new_source_sha256':hashlib.sha256(d['after'].encode()).hexdigest(),'input_classification':'EXISTING_PRIVATE_CAPSULE_READ_NOT_CREDENTIAL_FREE','exact_input_hash_triples':expected,'source_parsed_only':True,'candidate_executed':False,'private_capsule_read':False,'Runtime_calls':0,'selected_owner_proven':False,'full_replacement_qualified':False}
print(json.dumps(result,sort_keys=True))

